sys_ui_page.client_script:
function closeWindow() {
    GlideDialogWindow.get().destroy();
}

function update_model() {
    var UpdateModel = new GlideAjax('UpdateModel2');
    UpdateModel.addParam('sysparm_name','setModel');
    UpdateModel.addParam('sysparm_ID', g_form.getUniqueValue());
    UpdateModel.getXML(setmodel);
}

function setmodel(response){
    var resultrun = response.responseXML.documentElement.getAttribute("answer");
	if (resultrun == "0") {
      GlideDialogWindow.get().destroy();
	} else {
      alert("error");
	}
}
